      toolName: event.toolName,
      args: event.args,
      elapsed: event.elapsed,
      action: event.action,
      detail: pipeline.redact(event.detail),
      timestamp: event.timestamp,
    );
  }
  _sendSafely(_protocol.encodeEvent(event), client);
}

