/// The pure protocol server over this CLI's agent seams.
WireServeServer _wireServeServer(void Function(String line)? onDiagnostic) =>
    WireServeServer(
      runPrompt: _runPrompt,
      steer: _steerResolved,
      abort: _abortIfBusy,
